CREATE PROCEDURE [dbo].[PR_LOG2_RUNLOG]
@p_event_dttm datetime, @p_master_id nvarchar(150), @p_plan_id nvarchar(150), @p_proc_name nvarchar(150), @p_log_type nvarchar(30), @p_descr nvarchar(MAX)
